/**
 * SliceImage — a generated SVG meant for `border-image`: `slice` is the inset
 * (in SVG units, which are CSS px here) that keeps the ornamented ends whole,
 * `border` the depth its rules or outline occupy.
 */
export type SliceImage = {
  readonly svg: string;
  readonly slice: number;
  readonly border: number;
};
